public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            // Validate maxRows
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            // Validate fields
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('fields must contain at least one field.');
            }

            // Validate object API name
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name is required.');
            }

            // Resolve SObjectType
            Schema.SObjectType sObjType = getSObjectType(objectApiName);
            if (sObjType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();

            // Check object accessibility
            if (!objDescribe.isAccessible()) {
                throw new SearchException('You do not have read access to object: ' + objectApiName);
            }

            // Build case-insensitive field map
            Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
            Map<String, Schema.SObjectField> lowerCaseFieldMap = new Map<String, Schema.SObjectField>();
            for (String fieldName : fieldMap.keySet()) {
                lowerCaseFieldMap.put(fieldName.toLowerCase(), fieldMap.get(fieldName));
            }

            // Validate Id field accessibility
            Schema.SObjectField idField = lowerCaseFieldMap.get('id');
            if (idField == null || !idField.getDescribe().isAccessible()) {
                throw new SearchException('You do not have read access to the Id field.');
            }

            // Collect query fields
            List<String> queryFields = new List<String>();
            queryFields.add('Id');

            Set<String> addedFields = new Set<String>();
            addedFields.add('id');

            for (String field : fields) {
                if (String.isBlank(field)) {
                    throw new SearchException('Field name cannot be blank.');
                }
                Schema.SObjectField sField = lowerCaseFieldMap.get(field.toLowerCase());
                if (sField == null) {
                    throw new SearchException('Field does not exist: ' + field);
                }
                Schema.DescribeFieldResult fDescribe = sField.getDescribe();
                if (!fDescribe.isAccessible()) {
                    throw new SearchException('You do not have read access to field: ' + field);
                }
                String actualFieldName = fDescribe.getName();
                if (!addedFields.contains(actualFieldName.toLowerCase())) {
                    queryFields.add(actualFieldName);
                    addedFields.add(actualFieldName.toLowerCase());
                }
            }

            // Build WHERE conditions and bind map
            List<String> whereConditions = new List<String>();
            Map<String, Object> bindMap = new Map<String, Object>();
            Integer bindIndex = 0;

            if (filters != null && !filters.isEmpty()) {
                for (String filterField : filters.keySet()) {
                    if (String.isBlank(filterField)) {
                        throw new SearchException('Filter field name cannot be blank.');
                    }
                    Schema.SObjectField sField = lowerCaseFieldMap.get(filterField.toLowerCase());
                    if (sField == null) {
                        throw new SearchException('Filter field does not exist: ' + filterField);
                    }
                    Schema.DescribeFieldResult fDescribe = sField.getDescribe();
                    if (!fDescribe.isAccessible()) {
                        throw new SearchException('You do not have read access to filter field: ' + filterField);
                    }
                    if (!fDescribe.isFilterable()) {
                        throw new SearchException('Filter field cannot be filtered: ' + filterField);
                    }
                    String bindName = 'filter' + bindIndex;
                    bindIndex++;
                    whereConditions.add(fDescribe.getName() + ' = :' + bindName);
                    bindMap.put(bindName, filters.get(filterField));
                }
            }

            // Validate order by field
            String orderByClause = '';
            if (String.isNotBlank(orderByField)) {
                Schema.SObjectField sField = lowerCaseFieldMap.get(orderByField.toLowerCase());
                if (sField == null) {
                    throw new SearchException('Order by field does not exist: ' + orderByField);
                }
                Schema.DescribeFieldResult fDescribe = sField.getDescribe();
                if (!fDescribe.isAccessible()) {
                    throw new SearchException('You do not have read access to order by field: ' + orderByField);
                }
                if (!fDescribe.isSortable()) {
                    throw new SearchException('Order by field cannot be sorted: ' + orderByField);
                }
                orderByClause = ' ORDER BY ' + fDescribe.getName() + ' ASC';
            }

            // Build query string
            String queryString = 'SELECT ' + String.join(queryFields, ', ') + ' FROM ' + objDescribe.getName();
            if (!whereConditions.isEmpty()) {
                queryString += ' WHERE ' + String.join(whereConditions, ' AND ');
            }
            queryString += orderByClause;
            queryString += ' LIMIT ' + maxRows;

            // Execute query with USER_MODE to enforce sharing and FLS
            return Database.queryWithBinds(queryString, bindMap, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }

    private static Schema.SObjectType getSObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sObjType = globalDescribe.get(objectApiName);
        if (sObjType != null) {
            return sObjType;
        }
        String lowerName = objectApiName.toLowerCase();
        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase() == lowerName) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }
}
