public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;

        public Order() {
            this.lines = new List<Line>();
            this.total = 0;
        }
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;

        public Line() {
            this.discount = 0;
        }
    }

    public static Order parse(String body) {
        if (body == null || String.isBlank(body)) {
            throw new PayloadException('Payload body is required.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Payload is not valid JSON.');
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Payload must be a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        String orderNumber = getString(root, 'number');
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Order number is required.');
        }

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = parseDate(getString(root, 'date'));
        order.currencyCode = getString(root, 'currency');
        order.customerEmail = getCustomerEmail(root);

        Object linesObj = root.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('lines must be an array.');
            }
            List<Object> rawLines = (List<Object>) linesObj;
            for (Object lineObj : rawLines) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line must be an object.');
                }
                Line line = parseLine((Map<String, Object>) lineObj);
                order.lines.add(line);
                order.total = order.total.add(line.lineTotal);
            }
        }

        return order;
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is required.');
        }

        Integer lineCount = 0;
        if (order.lines != null) {
            lineCount = order.lines.size();
        }

        Decimal total = order.total;
        if (total == null) {
            total = 0;
        }

        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', lineCount);
        ack.put('total', total);
        return JSON.serialize(ack);
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        line.sku = getString(lineMap, 'sku');
        if (String.isBlank(line.sku)) {
            throw new PayloadException('Line SKU is required.');
        }

        line.quantity = getInteger(lineMap, 'quantity');
        if (line.quantity == null || line.quantity <= 0) {
            throw new PayloadException('Line quantity must be a positive integer.');
        }

        line.unitPrice = getDecimal(lineMap, 'unitPrice');
        if (line.unitPrice == null || line.unitPrice < 0) {
            throw new PayloadException('Line unit price must be non-negative.');
        }

        line.discount = getDecimal(lineMap, 'discount');
        if (line.discount == null) {
            line.discount = 0;
        }

        Decimal rawTotal = line.quantity * line.unitPrice * (1 - line.discount);
        line.lineTotal = rawTotal.setScale(2, RoundingMode.HALF_UP);

        return line;
    }

    private static String getCustomerEmail(Map<String, Object> root) {
        Object customerObj = root.get('customer');
        if (customerObj == null) {
            return null;
        }
        if (!(customerObj instanceof Map<String, Object>)) {
            throw new PayloadException('customer must be an object.');
        }
        Map<String, Object> customer = (Map<String, Object>) customerObj;
        return getString(customer, 'email');
    }

    private static Date parseDate(String value) {
        if (String.isBlank(value)) {
            return null;
        }
        try {
            return Date.valueOf(value);
        } catch (Exception e) {
            throw new PayloadException('Invalid order date.');
        }
    }

    private static String getString(Map<String, Object> source, String key) {
        Object value = source.get(key);
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        throw new PayloadException('Expected a string for ' + key + '.');
    }

    private static Decimal getDecimal(Map<String, Object> source, String key) {
        Object value = source.get(key);
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if ((value instanceof Integer) || (value instanceof Long) || (value instanceof Double)) {
            try {
                return Decimal.valueOf(String.valueOf(value));
            } catch (Exception e) {
                throw new PayloadException('Expected a number for ' + key + '.');
            }
        }
        throw new PayloadException('Expected a number for ' + key + '.');
    }

    private static Integer getInteger(Map<String, Object> source, String key) {
        Decimal decimalValue = getDecimal(source, key);
        if (decimalValue == null) {
            return null;
        }
        Decimal truncated = decimalValue.setScale(0, RoundingMode.DOWN);
        if (decimalValue != truncated) {
            throw new PayloadException('Expected an integer for ' + key + '.');
        }
        return decimalValue.intValue();
    }
}
