/**
 * Unit tests for ShippingCostCalculator.
 *
 * They cover every documented behaviour of the calculator:
 *  - the weight tiers and their exact boundaries (1, 5 and 20 kg),
 *  - the "per started kilogram" surcharge above 20 kg,
 *  - the zone multipliers and the case-insensitive zone matching,
 *  - the express surcharge and the "null means standard" rule,
 *  - free shipping for large DOMESTIC standard orders,
 *  - half-up rounding to two decimal places,
 *  - the ShippingException cases (null/zero/negative weight, null/unknown zone).
 *
 * No org data is used (no SeeAllData) and the calculator is a pure function,
 * so the tests are fully self contained.
 */
@isTest
private class ShippingCostCalculatorTest {

    // ------------------------------------------------------------------
    // Weight tiers and their boundaries
    // ------------------------------------------------------------------

    @isTest
    static void basePriceFollowsWeightTiers() {
        // Up to and including 1 kg -> 5.00
        assertQuote('0.5 kg', 5.00, 0.5, 'DOMESTIC', false, null);
        assertQuote('1 kg (upper boundary of the first tier)', 5.00, 1, 'DOMESTIC', false, null);

        // Above 1 kg and up to and including 5 kg -> 9.50
        assertQuote('1.01 kg (just above the first tier)', 9.50, 1.01, 'DOMESTIC', false, null);
        assertQuote('3 kg', 9.50, 3, 'DOMESTIC', false, null);
        assertQuote('5 kg (upper boundary of the second tier)', 9.50, 5, 'DOMESTIC', false, null);

        // Above 5 kg and up to and including 20 kg -> 18.00
        assertQuote('5.01 kg (just above the second tier)', 18.00, 5.01, 'DOMESTIC', false, null);
        assertQuote('12 kg', 18.00, 12, 'DOMESTIC', false, null);
        assertQuote('20 kg (upper boundary of the third tier)', 18.00, 20, 'DOMESTIC', false, null);
    }

    @isTest
    static void weightAboveTwentyKgChargesForEveryStartedKilogram() {
        assertQuote('20.01 kg (first started kilogram)', 18.75, 20.01, 'DOMESTIC', false, null);
        assertQuote('20.1 kg (documented example)', 18.75, 20.1, 'DOMESTIC', false, null);
        assertQuote('20.5 kg', 18.75, 20.5, 'DOMESTIC', false, null);
        assertQuote('21 kg (exactly one started kilogram)', 18.75, 21, 'DOMESTIC', false, null);
        assertQuote('22 kg (documented example)', 19.50, 22, 'DOMESTIC', false, null);
        assertQuote('30 kg', 25.50, 30, 'DOMESTIC', false, null);
        assertQuote('40.5 kg', 33.75, 40.5, 'DOMESTIC', false, null);
    }

    // ------------------------------------------------------------------
    // Zones
    // ------------------------------------------------------------------

    @isTest
    static void zoneMultipliesTheBasePrice() {
        assertQuote('1 kg DOMESTIC', 5.00, 1, 'DOMESTIC', false, null);
        assertQuote('1 kg EU', 7.00, 1, 'EU', false, null);
        assertQuote('1 kg WORLD', 11.00, 1, 'WORLD', false, null);

        assertQuote('5 kg DOMESTIC', 9.50, 5, 'DOMESTIC', false, null);
        assertQuote('5 kg EU', 13.30, 5, 'EU', false, null);
        assertQuote('5 kg WORLD', 20.90, 5, 'WORLD', false, null);

        assertQuote('20 kg DOMESTIC', 18.00, 20, 'DOMESTIC', false, null);
        assertQuote('20 kg EU', 25.20, 20, 'EU', false, null);
        assertQuote('20 kg WORLD', 39.60, 20, 'WORLD', false, null);

        assertQuote('21 kg EU', 26.25, 21, 'EU', false, null);
        assertQuote('21 kg WORLD', 41.25, 21, 'WORLD', false, null);
        assertQuote('22 kg EU', 27.30, 22, 'EU', false, null);
        assertQuote('22 kg WORLD', 42.90, 22, 'WORLD', false, null);
    }

    @isTest
    static void zoneMatchingIsCaseInsensitive() {
        assertQuote('uppercase DOMESTIC', 5.00, 1, 'DOMESTIC', false, null);
        assertQuote('lowercase domestic', 5.00, 1, 'domestic', false, null);
        assertQuote('mixed case Domestic', 5.00, 1, 'Domestic', false, null);

        assertQuote('lowercase eu', 7.00, 1, 'eu', false, null);
        assertQuote('mixed case eU', 7.00, 1, 'eU', false, null);

        assertQuote('lowercase world', 11.00, 1, 'world', false, null);
        assertQuote('mixed case WoRlD', 11.00, 1, 'WoRlD', false, null);
    }

    // ------------------------------------------------------------------
    // Express
    // ------------------------------------------------------------------

    @isTest
    static void expressDeliveryAddsFiftyPercent() {
        assertQuote('1 kg DOMESTIC express', 7.50, 1, 'DOMESTIC', true, null);
        assertQuote('1 kg EU express', 10.50, 1, 'EU', true, null);
        assertQuote('1 kg WORLD express', 16.50, 1, 'WORLD', true, null);

        assertQuote('5 kg DOMESTIC express', 14.25, 5, 'DOMESTIC', true, null);
        assertQuote('5 kg EU express', 19.95, 5, 'EU', true, null);
        assertQuote('5 kg WORLD express', 31.35, 5, 'WORLD', true, null);

        assertQuote('20 kg DOMESTIC express', 27.00, 20, 'DOMESTIC', true, null);
        assertQuote('20 kg EU express', 37.80, 20, 'EU', true, null);
        assertQuote('20 kg WORLD express', 59.40, 20, 'WORLD', true, null);

        assertQuote('21 kg DOMESTIC express (documented example)', 28.13, 21, 'DOMESTIC', true, null);
        assertQuote('21 kg EU express', 39.38, 21, 'EU', true, null);
        assertQuote('21 kg WORLD express', 61.88, 21, 'WORLD', true, null);
        assertQuote('22 kg DOMESTIC express', 29.25, 22, 'DOMESTIC', true, null);
    }

    @isTest
    static void nullExpressFlagMeansStandardDelivery() {
        assertQuote('1 kg DOMESTIC with a null express flag', 5.00, 1, 'DOMESTIC', null, null);
        assertQuote('1 kg EU with a null express flag', 7.00, 1, 'EU', null, null);
        assertQuote('1 kg WORLD with a null express flag', 11.00, 1, 'WORLD', null, null);
        assertQuote('21 kg DOMESTIC with a null express flag', 18.75, 21, 'DOMESTIC', null, null);
        assertQuote('21 kg WORLD with a null express flag', 41.25, 21, 'WORLD', null, null);

        // A null express flag is a standard delivery, so the free shipping rule still applies.
        assertFreeQuote('DOMESTIC null express with a large order value', 1, 'DOMESTIC', null, 200);
    }

    // ------------------------------------------------------------------
    // Free shipping
    // ------------------------------------------------------------------

    @isTest
    static void domesticStandardOrdersOverTheThresholdShipFree() {
        assertQuote('order value exactly 100.00', 0, 1, 'DOMESTIC', false, 100);
        assertQuote('order value above the threshold', 0, 1, 'DOMESTIC', false, 100.01);
        assertQuote('large order value', 0, 1, 'DOMESTIC', false, 250);
        assertQuote('free for a light parcel', 0, 0.5, 'DOMESTIC', false, 500);
        assertQuote('free for a heavy parcel', 0, 100, 'DOMESTIC', false, 500);
        assertQuote('free for a heavy parcel just above 20 kg', 0, 21, 'DOMESTIC', false, 100);
        assertQuote('free shipping also matches a lowercase zone', 0, 3, 'domestic', false, 100);
    }

    @isTest
    static void freeShippingDoesNotApplyOutsideItsConditions() {
        // Just below the threshold.
        assertQuote('order value 99.99', 5.00, 1, 'DOMESTIC', false, 99.99);
        assertQuote('order value 99.999', 5.00, 1, 'DOMESTIC', false, 99.999);
        // No order value at all.
        assertQuote('null order value', 5.00, 1, 'DOMESTIC', false, null);
        assertQuote('zero order value', 5.00, 1, 'DOMESTIC', false, 0);
        // Express is never free.
        assertQuote('DOMESTIC express with a large order value', 7.50, 1, 'DOMESTIC', true, 500);
        // Only DOMESTIC is free.
        assertQuote('EU with a large order value', 7.00, 1, 'EU', false, 500);
        assertQuote('WORLD with a large order value', 11.00, 1, 'WORLD', false, 500);
    }

    // ------------------------------------------------------------------
    // Rounding
    // ------------------------------------------------------------------

    @isTest
    static void pricesAreRoundedHalfUpToTwoDecimalPlaces() {
        // 18.75 * 1.5 = 28.125 -> 28.13 with HALF_UP (HALF_EVEN / HALF_DOWN would give 28.12)
        assertQuote('21 kg DOMESTIC express', 28.13, 21, 'DOMESTIC', true, null);
        // 20.25 * 1.4 * 1.5 = 42.525 -> 42.53 (HALF_EVEN would give 42.52)
        assertQuote('23 kg EU express', 42.53, 23, 'EU', true, null);
        // 20.25 * 2.2 * 1.5 = 66.825 -> 66.83 (HALF_EVEN would give 66.82)
        assertQuote('23 kg WORLD express', 66.83, 23, 'WORLD', true, null);
        // 21.75 * 1.5 = 32.625 -> 32.63 (HALF_EVEN would give 32.62)
        assertQuote('25 kg DOMESTIC express', 32.63, 25, 'DOMESTIC', true, null);
        // 18.75 * 2.2 * 1.5 = 61.875 -> 61.88
        assertQuote('21 kg WORLD express', 61.88, 21, 'WORLD', true, null);
        // 18.75 * 1.4 * 1.5 = 39.375 -> 39.38
        assertQuote('21 kg EU express', 39.38, 21, 'EU', true, null);
    }

    // ------------------------------------------------------------------
    // Errors
    // ------------------------------------------------------------------

    @isTest
    static void invalidWeightThrowsShippingException() {
        assertThrowsShippingException('null weight', null, 'DOMESTIC', false, null);
        assertThrowsShippingException('zero weight', 0, 'DOMESTIC', false, null);
        assertThrowsShippingException('negative weight', -1, 'DOMESTIC', false, null);
        assertThrowsShippingException('tiny negative weight, EU express', -0.01, 'EU', true, 500);
        // The weight is validated before the zone, even when both are invalid.
        assertThrowsShippingException('null weight with an unknown zone', null, 'MARS', false, null);
    }

    @isTest
    static void invalidZoneThrowsShippingException() {
        assertThrowsShippingException('null zone', 1, null, false, null);
        assertThrowsShippingException('unknown zone', 1, 'MARS', false, null);
        assertThrowsShippingException('empty zone', 1, '', false, null);
        assertThrowsShippingException('blank zone', 1, '   ', false, null);
        assertThrowsShippingException('zone with a trailing space', 1, 'DOMESTIC ', false, null);
        assertThrowsShippingException('zone with a leading space', 1, ' EU', false, null);
        assertThrowsShippingException('two zones in one string', 1, 'DOMESTIC,EU', false, null);
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    /**
     * Asserts that the quote for the given arguments equals the expected amount and that the
     * amount is scaled to exactly two decimal places (the documented rounding).
     */
    private static void assertQuote(String label, Decimal expected, Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        Decimal actual = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        System.assert(actual == expected, label + ': expected ' + expected + ' but got ' + actual);
        System.assert(actual.scale() == 2, label + ': expected a value rounded to 2 decimal places but got ' + actual);
    }

    /** Asserts that the quote is free (0) - the free quotes are returned as a plain zero. */
    private static void assertFreeQuote(String label, Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        Decimal actual = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        System.assert(actual == 0, label + ': expected a free quote (0) but got ' + actual);
    }

    /** Asserts that the given arguments make the calculator throw a ShippingException. */
    private static void assertThrowsShippingException(String label, Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        try {
            ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
            System.assert(false, label + ': expected a ShippingException but none was thrown');
        } catch (ShippingCostCalculator.ShippingException e) {
            System.assertNotEquals(null, e.getMessage(), label + ': the ShippingException should carry a message');
        }
    }
