public with sharing class PicklistService {
    public class PicklistServiceException extends Exception {}

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names must not be null or blank.');
        }

        try {
            Schema.SObjectType sObjType = getSObjectType(objectApiName);
            if (sObjType == null) {
                throw new PicklistServiceException('Object not found: ' + objectApiName);
            }

            Schema.SObjectField field = getField(sObjType, fieldApiName);
            if (field == null) {
                throw new PicklistServiceException('Field not found: ' + fieldApiName + ' on object ' + objectApiName);
            }

            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            Schema.DisplayType displayType = fieldDescribe.getType();
            if (displayType != Schema.DisplayType.PICKLIST && displayType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException('Field ' + fieldApiName + ' is not a picklist or multi-select picklist.');
            }

            List<Option> options = new List<Option>();
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry.isActive()) {
                    Option opt = new Option();
                    opt.value = entry.getValue();
                    opt.label = entry.getLabel();
                    opt.isDefault = entry.isDefaultValue();
                    options.add(opt);
                }
            }
            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(e.getMessage());
        }
    }

    private static Schema.SObjectType getSObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    private static Schema.SObjectField getField(Schema.SObjectType sObjType, String fieldApiName) {
        Map<String, Schema.SObjectField> fieldMap = sObjType.getDescribe().fields.getMap();
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                return fieldMap.get(key);
            }
        }
        return null;
    }
}
