public without sharing class OpportunityPipelineHandler {
    public static void handle() {
        Set<Id> accountIds = new Set<Id>();

        if (Trigger.isInsert) {
            for (Opportunity opp : Trigger.new) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUpdate) {
            for (Opportunity opp : Trigger.new) {
                Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
                Boolean wasOpen = !oldOpp.IsClosed;
                Boolean isOpen = !opp.IsClosed;
                Boolean accountChanged = oldOpp.AccountId != opp.AccountId;
                Boolean amountChanged = oldOpp.Amount != opp.Amount;

                if (accountChanged) {
                    if (wasOpen && oldOpp.AccountId != null) {
                        accountIds.add(oldOpp.AccountId);
                    }
                    if (isOpen && opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                } else {
                    if (wasOpen != isOpen || (isOpen && amountChanged)) {
                        if (opp.AccountId != null) {
                            accountIds.add(opp.AccountId);
                        }
                    }
                }
            }
        } else if (Trigger.isDelete) {
            for (Opportunity opp : Trigger.old) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUndelete) {
            for (Opportunity opp : Trigger.new) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        recalculate(accountIds);
    }

    private static void recalculate(Set<Id> accountIds) {
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            pipelineByAccount.put(accountId, 0);
            countByAccount.put(accountId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');
            Integer openCount = (Integer) ar.get('openCount');
            pipelineByAccount.put(accountId, totalAmount == null ? 0 : totalAmount);
            countByAccount.put(accountId, openCount == null ? 0 : openCount);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newPipeline = pipelineByAccount.get(acc.Id);
            Integer newCount = countByAccount.get(acc.Id);
            if (newPipeline == null) {
                newPipeline = 0;
            }
            if (newCount == null) {
                newCount = 0;
            }

            if (acc.FB_Open_Pipeline__c != newPipeline || acc.FB_Open_Opportunities__c != newCount) {
                acc.FB_Open_Pipeline__c = newPipeline;
                acc.FB_Open_Opportunities__c = newCount;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
