/**
 * LogPurgeJob
 *
 * Nightly housekeeping job for FB_Integration_Log__c.
 *
 * Retention rules:
 *   - Logs whose Level__c is anything other than 'ERROR' (including blank/null)
 *     are deleted once they are more than 30 days old.
 *   - Logs whose Level__c is 'ERROR' are kept until they are more than 180 days old.
 *
 * The job deletes in chunks so a single execution can never blow the synchronous
 * DML row governor limit, and it uses the remaining DML budget of the running
 * transaction instead of a hard-coded number of records.
 *
 * Declared "without sharing" on purpose: this is a system housekeeping task and it
 * must purge every expired log regardless of the record access of the user who
 * scheduled the job.
 */
public without sharing class LogPurgeJob implements Schedulable {

    /** Records fetched and deleted per chunk. */
    private static final Integer CHUNK_SIZE = 2000;

    /** Retention (in days) for logs that are not errors. */
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;

    /** Retention (in days) for ERROR logs. */
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Job name used by scheduleNightly(). */
    private static final String JOB_NAME = 'Log purge (nightly)';

    /** Daily at 02:00 (seconds minutes hours day-of-month month day-of-week). */
    private static final String CRON_EXPRESSION = '0 0 2 * * ?';

    /** Schedulable requires a public, no-argument constructor. */
    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        purgeExpiredLogs();
    }

    /**
     * Schedules this job to run every day at 02:00 under the name
     * 'Log purge (nightly)'.
     *
     * @return the Id of the scheduled job returned by System.schedule.
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_EXPRESSION, new LogPurgeJob());
    }

    /**
     * Deletes all logs that are past their retention window, chunk by chunk.
     *
     * @return the number of records successfully deleted by this call.
     */
    @TestVisible
    private static Integer purgeExpiredLogs() {
        DateTime nonErrorCutoff = DateTime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

        // Never try to delete more rows than this transaction is still allowed to.
        Integer deleteBudget = Limits.getLimitDmlRows() - Limits.getDmlRows();
        Integer deletedCount = 0;

        while (deletedCount < deleteBudget) {
            Integer chunkSize = Math.min(CHUNK_SIZE, deleteBudget - deletedCount);

            List<FB_Integration_Log__c> expiredLogs = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (
                        (Level__c != 'ERROR' OR Level__c = null)
                        AND CreatedDate < :nonErrorCutoff
                    )
                    OR (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
                LIMIT :chunkSize
            ];

            if (expiredLogs.isEmpty()) {
                break;
            }

            // allOrNone = false: one undeletable record must not roll back the chunk.
            List<Database.DeleteResult> results = Database.delete(expiredLogs, false);

            Integer deletedInChunk = 0;
            for (Database.DeleteResult result : results) {
                if (result.isSuccess()) {
                    deletedInChunk++;
                }
            }
            deletedCount += deletedInChunk;

            // Nothing could be deleted (validation rule, lock, ...): stop instead of
            // re-querying and retrying the very same records forever.
            if (deletedInChunk == 0) {
                break;
            }
        }

        return deletedCount;
    }
}
