@IsTest
private class OpportunitiesServiceTest {

    private static final Decimal VALID_DISCOUNT = 10;

    /**
     * Container that wires up fresh mocks for a single test method and injects
     * them into the Application factories. Using a per-test container (instead
     * of static state) keeps the tests independent from each other.
     */
    private class MockSet {
        public final fflib_ApexMocks mocks = new fflib_ApexMocks();
        public final IOpportunitiesSelector selector;
        public final IOpportunities domain;
        public final fflib_ISObjectUnitOfWork uow;

        public MockSet() {
            selector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
            domain = (IOpportunities) mocks.mock(IOpportunities.class);
            uow = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

            Application.Selector.setMock(selector);
            Application.Domain.setMock(domain);
            Application.UnitOfWork.setMock(uow);
        }
    }

    private static Set<Id> fakeIds(Integer howMany) {
        Set<Id> ids = new Set<Id>();
        for (Integer i = 0; i < howMany; i++) {
            ids.add(fflib_IDGenerator.generate(Opportunity.SObjectType));
        }
        return ids;
    }

    private static List<Opportunity> fakeOpportunities(Integer howMany) {
        List<Opportunity> opportunities = new List<Opportunity>();
        for (Integer i = 0; i < howMany; i++) {
            opportunities.add(new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                Name = 'Test Opportunity ' + i,
                Amount = 100
            ));
        }
        return opportunities;
    }

    // ---------------------------------------------------------------------
    // discountPercentage validation
    // ---------------------------------------------------------------------

    @IsTest
    static void throwsExceptionWhenDiscountIsNull() {
        MockSet mocks = new MockSet();
        Set<Id> ids = fakeIds(1);

        OpportunitiesService.OpportunitiesServiceException caught;
        try {
