        // Neither the domain nor the unit of work may be touched.
        ((IOpportunities) mocks.mocks.verify(mocks.domain, 0)).applyDiscount(null, mocks.uow);
        ((fflib_ISObjectUnitOfWork) mocks.mocks.verify(mocks.uow, 0)).commitWork();
