    }

    @IsTest
    static void appliesDiscountToEmptyResultWithoutError() {
        MockSet mocks = new MockSet();
        Set<Id> ids = fakeIds(1);
        List<Opportunity> noMatches = new List<Opportunity>();

        mocks.mocks.startStubbing();
        mocks.mocks.when(mocks.selector.selectById(ids)).thenReturn(noMatches);
        mocks.mocks.stopStubbing();

        OpportunitiesService.applyDiscounts(ids, VALID_DISCOUNT);

        // Even when the selector returns nothing the domain is still asked to
        // apply the discount and the work is still committed.
        ((IOpportunities) mocks.mocks.verify(mocks.domain, 1)).applyDiscount(VALID_DISCOUNT, mocks.uow);
        ((fflib_ISObjectUnitOfWork) mocks.mocks.verify(mocks.uow, 1)).commitWork();
    }
