/**
 * Domain class for the Opportunity SObject.
 *
 * Applies default values when Opportunities are created:
 *  - CloseDate defaults to today + 30 days
 *  - Type defaults to 'New Customer'
 *
 * Existing values are preserved. fflib_SObjectDomain calls onApplyDefaults()
 * only during the before insert context, so defaults are not applied on update.
 */
public with sharing class Opportunities extends fflib_SObjectDomain {

    /**
     * @param opportunities The Opportunity records in the current trigger context.
     */
    public Opportunities(List<Opportunity> opportunities) {
        super(opportunities);
    }

    /**
     * Factory used by fflib_SObjectDomain.triggerHandler() to instantiate the domain.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * Applies default values to newly created Opportunities.
     * This hook is invoked by fflib_SObjectDomain only during before insert.
     */
    public override void onApplyDefaults() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.CloseDate == null) {
                opp.CloseDate = Date.today().addDays(30);
            }
            if (String.isBlank(opp.Type)) {
                opp.Type = 'New Customer';
            }
        }
    }
}
