/**
 * Account domain.
 *
 * Follows the newer fflib domain structure: the domain is a plain collection
 * class on top of fflib_SObjects, and all creation goes through the
 * Application.Domain factory so unit tests can substitute a mock.
 */
public class Accounts extends fflib_SObjects implements IAccounts {

    /**
     * Build a domain from already-loaded Account records via the domain factory.
     */
    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newInstance(Account.SObjectType, records);
    }

    /**
     * Build a domain from Account Ids. The factory resolves the records through
     * its selector (Application.Selector -> AccountsSelector).
     */
    public static IAccounts newInstance(Set<Id> accountIds) {
        return (IAccounts) Application.Domain.newInstance(Account.SObjectType, accountIds);
    }

    /**
     * Domain factory constructor used by fflib_Application.DomainFactory.
     */
    public class Constructor implements fflib_Application.IDomainFactory {
        public fflib_ISObjects newInstance(List<SObject> records) {
            return new Accounts(records);
        }

        public fflib_ISObjects newInstance(Set<Id> ids) {
            return new Accounts(ids);
        }
    }

    public Accounts(List<SObject> records) {
        super(records, Account.SObjectType);
    }

    public Accounts(Set<Id> accountIds) {
        super(
            Application.Selector.newInstance(Account.SObjectType).selectSObjectsById(accountIds),
            Account.SObjectType
        );
    }

    /**
     * getSObjectType() / getType() are inherited from fflib_SObjects and report Account
     * because the base class is constructed with Account.SObjectType.
     */

    public List<Account> getAccounts() {
        return (List<Account>) getRecords();
    }

    /**
     * Returns a new domain containing only the records whose Rating matches.
     * The current domain is left untouched.
     */
    public IAccounts selectByRating(String rating) {
        List<Account> matching = new List<Account>();
        for (Account acc : getAccounts()) {
            if (acc.Rating == rating) {
                matching.add(acc);
            }
        }
        return Accounts.newInstance(matching);
    }

    /**
     * Distinct, non-null OwnerId values across the domain.
     */
    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account acc : getAccounts()) {
            if (acc.OwnerId != null) {
                ownerIds.add(acc.OwnerId);
            }
        }
        return ownerIds;
    }

    /**
     * Sets Rating on every record in the domain.
     */
    public void setRating(String rating) {
        for (Account acc : getAccounts()) {
            acc.Rating = rating;
        }
    }
}
