        // sortSelectFields = true, data access = USER_MODE.
        // USER_MODE makes the platform enforce object/field/sharing access,
        // so the manual CRUD/FLS checks of the legacy mode are not needed.
        super(true, false, false, true, fflib_SObjectSelector.DataAccess.USER_MODE);
    }

