/**
 * Service responsible for escalating Cases.
 *
 * Escalating a Case means flagging it as escalated, raising its priority to High
 * and creating a follow-up Task assigned to the Case owner.
 */
public with sharing class CaseEscalationService {

    /** Thrown when the service is called without a valid escalation reason. */
    public class EscalationException extends Exception {}

    private static final String STATUS_CLOSED = 'Closed';
    private static final String PRIORITY_HIGH = 'High';

    /**
     * Escalates the given Cases.
     *
     * @param caseIds Cases to consider for escalation. Null or empty is a no-op.
     * @param reason  Reason for the escalation. Required (blank throws).
     */
    public static void escalate(Set<Id> caseIds, String reason) {
        // Validate the reason before touching the database in any way.
        if (String.isBlank(reason)) {
            throw new EscalationException('An escalation reason is required.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Date dueDate = Date.today().addDays(1);
        Boolean anyEscalated = false;

        for (Case c : cases) {
            if (c.Status == STATUS_CLOSED || c.IsEscalated == true) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = PRIORITY_HIGH;
            uow.registerDirty(c);

            uow.registerNew(new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = dueDate,
                Priority = PRIORITY_HIGH
            ));

            anyEscalated = true;
        }

        if (anyEscalated) {
            uow.commitWork();
        }
    }
}
