/**
 * Service that onboards Accounts together with their Contacts.
 *
 * All records are persisted through a single fflib_SObjectUnitOfWork so that
 * the framework performs the DML (no direct DML statements here) and the
 * parent/child relationship is resolved after the Account insert.
 */
public with sharing class AccountOnboardingService {

    /**
     * Creates one Account per map key and one Contact per last name in that
     * key's list, linking each Contact to its new Account.
     *
     * @param contactLastNamesByAccountName Account name -> Contact last names
     * @return The inserted Accounts with their Ids populated
     */
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // Account must be listed before Contact so the unit of work inserts
        // the parent records first.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        List<Account> newAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account newAccount = new Account(Name = accountName);
            newAccounts.add(newAccount);
            uow.registerNew(newAccount);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null || lastNames.isEmpty()) {
                continue;
            }

            List<Contact> newContacts = new List<Contact>();
            for (String lastName : lastNames) {
                newContacts.add(new Contact(LastName = lastName));
            }

            uow.registerNew(newContacts);
            // The unit of work sets Contact.AccountId once the Account has an Id.
            uow.registerRelationship(newContacts, Contact.AccountId, newAccount);
        }

        uow.commitWork();

        return newAccounts;
    }
}
