/**
 * Normalizes Contact.Phone values for the supplied Contact Ids.
 *
 * Notes on changes from the original outline:
 * - The class uses `with sharing` so the running user's sharing rules are enforced.
 * - Input Ids are deduplicated and nulls are removed before the SOQL query.
 * - Only Contacts with a non-blank Phone are put into the update list, so Contacts
 *   without a phone are left out of the DML as requested.
 * - The requested normalization keeps every digit and every '+' character. If the
 *   dialer strictly requires a single leading '+', additional normalization would be
 *   needed, but that would change the stated rule.
 */
public with sharing class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failedUpdates = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failedUpdates;
        }

        Set<Id> uniqueIds = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                uniqueIds.add(contactId);
            }
        }

        if (uniqueIds.isEmpty()) {
            return failedUpdates;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :uniqueIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contact : contacts) {
            if (String.isNotBlank(contact.Phone)) {
                contact.Phone = contact.Phone.replaceAll('[^0-9+]', '');
                contactsToUpdate.add(contact);
            }
        }

        List<Database.SaveResult> results = Database.update(contactsToUpdate, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedUpdates.put(
                    contactsToUpdate[i].Id,
                    results[i].getErrors()[0].getMessage()
                );
            }
        }

        return failedUpdates;
    }
}
