    // For large batches (e.g., nightly API cleanup of up to 200), use dispatcher jobs
    // that each enqueue up to 50 per-case jobs, preserving one-job-per-case isolation.
    final Integer MAX_JOBS_PER_TX = 50;
    if (newlyClosedCaseIds.size() <= MAX_JOBS_PER_TX) {
        for (Id caseId : newlyClosedCaseIds) {
