            Integer endIdx = Math.min(i + MAX_JOBS_PER_TX, newlyClosedCaseIds.size());
            List<Id> chunk = new List<Id>();
            for (Integer j = i; j < endIdx; j++) {
                chunk.add(newlyClosedCaseIds[j]);
            }
            System.enqueueJob(new CaseSurveyJob.Dispatcher(chunk));
        }
    }
