public with sharing class AccountCountrySync {
    public static void syncMailingCountry(List<Account> newAccounts, Map<Id, Account> oldAccounts) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccounts == null || oldAccounts.isEmpty()) {
            return;
        }

        Map<Id, Account> changedAccounts = new Map<Id, Account>();
        Set<Id> changedAccountIds = new Set<Id>();
        Set<String> oldBillingCountries = new Set<String>();

        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccounts.get(newAccount.Id);
            if (oldAccount == null) {
                continue;
            }

            if (newAccount.BillingCountry != oldAccount.BillingCountry) {
                changedAccounts.put(newAccount.Id, newAccount);
                changedAccountIds.add(newAccount.Id);

                if (String.isNotBlank(oldAccount.BillingCountry)) {
                    oldBillingCountries.add(oldAccount.BillingCountry);
                }
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // One query, scoped to the accounts whose BillingCountry changed.
        // The MailingCountry filter reduces rows to only contacts that could need the update.
        for (Contact contact : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
            AND (
                MailingCountry = null
                OR MailingCountry = ''
                OR MailingCountry IN :oldBillingCountries
            )
        ]) {
            Account newAccount = changedAccounts.get(contact.AccountId);
            Account oldAccount = oldAccounts.get(contact.AccountId);

            if (newAccount == null || oldAccount == null) {
                continue;
            }

            if (String.isBlank(contact.MailingCountry) || contact.MailingCountry == oldAccount.BillingCountry) {
                if (contact.MailingCountry != newAccount.BillingCountry) {
                    contact.MailingCountry = newAccount.BillingCountry;
                    contactsToUpdate.add(contact);
                }
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
```

