import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

import ACCOUNT_NAME_FIELD from '@salesforce/schema/Account.Name';
import ACCOUNT_INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ACCOUNT_ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import ACCOUNT_OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [
    ACCOUNT_NAME_FIELD,
    ACCOUNT_INDUSTRY_FIELD,
    ACCOUNT_ANNUAL_REVENUE_FIELD,
    ACCOUNT_OWNER_NAME_FIELD
];

export default class AccountHeader extends LightningElement {
    /**
     * Record Id provided by the Account record page. In a console, tabs are
     * reused, so this value can change while the component stays alive.
     */
    @api recordId;

    /**
     * The '$recordId' token makes the wire adapter reactive: whenever recordId
     * changes (new Account in a reused console tab), getRecord re-fetches the
     * record and the template re-renders. No imperative code needed.
     */
    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredAccount;

    get record() {
        return this.wiredAccount.data;
    }

    /** True until the wire has produced either data or an error. */
    get isLoading() {
        return !this.wiredAccount.data && !this.wiredAccount.error;
    }

    get errorMessage() {
        return this.wiredAccount.error?.body?.message;
    }

    get name() {
        return this.record?.fields?.Name?.value;
    }

    get industry() {
        return this.record?.fields?.Industry?.value;
    }

    get hasIndustry() {
        const industry = this.industry;
        return industry !== undefined && industry !== null && industry !== '';
    }

    get annualRevenue() {
        return this.record?.fields?.AnnualRevenue?.value;
    }

    get ownerName() {
        // Account.Owner.Name comes back as a nested record: fields.Owner.value.fields.Name.value
        return this.record?.fields?.Owner?.value?.fields?.Name?.value;
    }
}
