        if (this._connected && value && !this._initialLoadStarted) {
            this._initialLoadStarted = true;
            this.loadOpportunities();
        }
    }

    connectedCallback() {
        this._connected = true;
        if (this._recordId && !this._initialLoadStarted) {
            this._initialLoadStarted = true;
            this.loadOpportunities();
        }
    }

    async loadOpportunities() {
        if (!this._recordId) {
            return;
        }

        this.isLoading = true;
        this.error = undefined;
        this.opportunities = [];
        this.hasLoaded = false;

        try {
            const result = await getOpenOpportunities({ accountId: this._recordId });
            this.opportunities = result || [];
            this.hasLoaded = true;
        } catch (err) {
            this.error = err;
        } finally {
            this.isLoading = false;
        }
    }

    get hasOpportunities() {
        return this.opportunities && this.opportunities.length > 0;
    }

    get showEmpty() {
        return this.hasLoaded && !this.error && !this.hasOpportunities;
    }

    handleRetry() {
        this.loadOpportunities();
    }
}
