import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import LightningConfirm from 'lightning/confirm';
import { deleteRecord } from 'lightning/uiRecordApi';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Stage', fieldName: 'StageName', type: 'text' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    columns = COLUMNS;

    // Local copy of the parent's data so we can remove rows without mutating
    // the array owned by the parent component.
    data = [];

    @api
    get opportunities() {
        return this._opportunities;
    }

    set opportunities(value) {
        this._opportunities = value;
        this.data = Array.isArray(value) ? value.map((row) => ({ ...row })) : [];
    }

    async handleRowAction(event) {
        const action = event.detail.action;
        const row = event.detail.row;

        if (!action || !row) {
            return;
        }

        switch (action.name) {
            case 'view':
                this.navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                await this.deleteOpportunity(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId,
                objectApiName: 'Opportunity',
                actionName
            }
        });
    }

    async deleteOpportunity(row) {
        const confirmed = await LightningConfirm.open({
            label: 'Delete opportunity',
            message: `Are you sure you want to delete ${row.Name}?`,
            theme: 'warning'
        });

        // User cancelled: leave the row alone.
        if (!confirmed) {
            return;
        }

        try {
            await deleteRecord(row.Id);

            // Remove the row from the local copy only.
            this.data = this.data.filter((item) => item.Id !== row.Id);

            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'success',
                    title: 'Opportunity deleted'
                })
            );
        } catch (error) {
            // Keep the row in the table and surface the server error.
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Delete failed',
                    message: error && error.body ? error.body.message : 'Unknown error'
                })
            );
        }
    }
}
