    submitAll() {
        const editors = Array.from(this.template.querySelectorAll('c-line-item-editor'));
        let allValid = true;

        // Validate every editor so all invalid lines show their errors at once.
        editors.forEach((editor) => {
            if (!editor.validate()) {
                allValid = false;
            }
        });

        if (allValid) {
            const lines = editors.map((editor) => editor.getValue());
            this.showError = false;
            this.dispatchEvent(new CustomEvent('submit', { detail: { lines } }));
        } else {
            this.showError = true;
        }
    }
}
