import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    hasStats = false;
    error;

    _intervalId = null;
    _inFlight = false;
    _isActive = false;
    _requestId = 0;
    _onVisibilityChange = null;

    connectedCallback() {
        this._isActive = true;
        this._inFlight = false;
        this._requestId += 1;
        this._startPolling();
    }

    disconnectedCallback() {
        this._isActive = false;
        this._stopPolling();
    }

    _startPolling() {
        this._stopPolling();

        this._onVisibilityChange = this._handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._onVisibilityChange);

        if (document.visibilityState === 'visible') {
            this._startInterval();
            this._loadStats();
        }
    }

    _stopPolling() {
        this._stopInterval();

        if (this._onVisibilityChange) {
            document.removeEventListener('visibilitychange', this._onVisibilityChange);
            this._onVisibilityChange = null;
        }
    }

    _startInterval() {
        if (this._intervalId === null) {
            this._intervalId = window.setInterval(() => {
                this._loadStats();
            }, REFRESH_INTERVAL_MS);
        }
    }

    _stopInterval() {
        if (this._intervalId !== null) {
            window.clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    _handleVisibilityChange() {
        if (!this._isActive) {
            return;
        }

        if (document.visibilityState === 'hidden') {
            this._stopInterval();
        } else if (document.visibilityState === 'visible') {
            this._startInterval();
            this._loadStats();
        }
    }

    async _loadStats() {
        if (!this._isActive) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            return;
        }
        if (this._inFlight) {
            return;
        }

        this._inFlight = true;
        const requestId = ++this._requestId;

        try {
            const stats = await getQueueStats();

            if (!this._isActive || requestId !== this._requestId) {
                return;
            }

            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.hasStats = true;
            this.error = undefined;
        } catch (error) {
            if (!this._isActive || requestId !== this._requestId) {
                return;
            }

            const message = error && error.body && error.body.message
                ? error.body.message
                : 'Unknown error';
            this.error = { body: { message } };
        } finally {
            if (requestId === this._requestId) {
                this._inFlight = false;
            }
        }
    }
}
