import { LightningElement, api } from 'lwc';

let nextId = 0;

export default class StatusListbox extends LightningElement {
    @api label = '';

    _value = '';
    _options = [];
    _activeValue;
    _uniqueId;

    constructor() {
        super();
        this._uniqueId = `status-listbox-${nextId++}`;
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val || '';
        this._syncActiveToValue();
    }

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = val || [];
        this._syncActiveToOptions();
    }

    _syncActiveToValue() {
        const opts = this._options;
        if (opts.length === 0) {
            this._activeValue = undefined;
            return;
        }
        const valueExists = opts.some(o => o.value === this._value);
        this._activeValue = valueExists ? this._value : opts[0].value;
    }

    _syncActiveToOptions() {
        const opts = this._options;
        if (opts.length === 0) {
            this._activeValue = undefined;
            return;
        }
        const activeExists = opts.some(o => o.value === this._activeValue);
        if (activeExists) return;
        const valueExists = opts.some(o => o.value === this._value);
        this._activeValue = valueExists ? this._value : opts[0].value;
    }

    get renderedOptions() {
        return this._options.map((opt, index) => {
            const isSelected = opt.value === this._value;
            const isActive = opt.value === this._activeValue;
            let cssClass = 'slds-listbox__option slds-listbox__option_plain';
            if (isActive) cssClass += ' slds-is-active';
            if (isSelected) cssClass += ' slds-is-selected';
            return {
                id: `${this._uniqueId}-option-${index}`,
                index,
                value: opt.value,
                label: opt.label,
                isActive,
                isSelected,
                ariaSelected: isSelected ? 'true' : 'false',
                cssClass
            };
        });
    }

    get activeDescendantId() {
        const active = this.renderedOptions.find(opt => opt.isActive);
        return active ? active.id : '';
    }

    handleKeyDown(event) {
        const { key } = event;
        const opts = this._options;
        if (opts.length === 0) return;

        const activeIndex = opts.findIndex(o => o.value === this._activeValue);
        let newIndex = activeIndex;

        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                newIndex = Math.min(activeIndex + 1, opts.length - 1);
                break;
            case 'ArrowUp':
                event.preventDefault();
                newIndex = Math.max(activeIndex - 1, 0);
                break;
            case 'Home':
                event.preventDefault();
                newIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                newIndex = opts.length - 1;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectActiveOption();
                return;
            default:
                return;
        }

        if (newIndex !== activeIndex && newIndex >= 0 && newIndex < opts.length) {
            this._activeValue = opts[newIndex].value;
        }
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);
        const option = this._options[index];
        if (!option) return;
        this._activeValue = option.value;
        if (option.value !== this._value) {
            this._value = option.value;
            this.dispatchEvent(new CustomEvent('change', { detail: { value: option.value } }));
        }
    }

    _selectActiveOption() {
        const activeValue = this._activeValue;
        if (activeValue === undefined) return;
        if (activeValue === this._value) return;
        this._value = activeValue;
        this.dispatchEvent(new CustomEvent('change', { detail: { value: activeValue } }));
    }
