import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    // Public: exactly the value the parent set (never overwritten by the component).
    @api heading;

    // Public: the parent's array is only ever read, never stored in `items` directly
    // and never mutated. A new array from the parent replaces the working copy.
    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = Array.isArray(value) ? value : [];
        this.items = this._tasks.map((task) => ({ ...task }));
    }

    // Private working copy: the component owns these objects.
    items = [];
    newLabel = '';
    nextId = 1;

    get displayHeading() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            // Empty / whitespace-only: nothing added, no event.
            return;
        }

        this.items = [...this.items, { id: this.generateId(), label, done: false }];
        this.newLabel = '';

        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        const done = event.target.checked;

        // New array + new task objects so the parent's data stays untouched
        // and the template re-renders.
        this.items = this.items.map((task) => (task.id === id ? { ...task, done } : task));
    }

    generateId() {
        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (this.items.some((task) => task.id === id));
        return id;
    }
}
