/**
 * EmployerService
 *
 * Keeps NPSP Affiliations in sync with the employer a donor supplies on the web form.
 *
 * Post-conditions for every Contact / Organization pair passed in:
 *   - a Current, Primary npe5__Affiliation__c exists between the Contact and the Organization;
 *   - Contact.npsp__Primary_Affiliation__c points at that Organization (NPSP keeps that lookup
 *     in sync when we use its standard mechanism, i.e. the Primary checkbox on the Affiliation);
 *   - a previous primary employer is left behind as a Former, non-primary Affiliation with an
 *     End Date of today;
 *   - the Contact is never moved out of its Household Account (Contact.AccountId is never touched).
 *
 * Bulk safe: 2 SOQL queries and 2 DML statements of our own, no matter how many Contacts arrive.
 * The Affiliation record is the source of truth for "primary employer"; we never insert a second
 * Affiliation for an Organization the Contact is already affiliated with.
 */
public with sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';
    private static final String STATUS_FORMER  = 'Former';

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            if (contactId != null && employerByContactId.get(contactId) != null) {
                contactIds.add(contactId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // -------------------------------------------------------------------
        // Query 1 of 2 - the Contacts.
        // Confirms the Ids are real (so a bad key cannot blow up the whole
        // transaction) and gives us the current Primary Affiliation lookup.
        // -------------------------------------------------------------------
        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        // -------------------------------------------------------------------
        // Query 2 of 2 - every Affiliation of those Contacts that could be
        // touched: the one that is primary today, plus any Current Affiliation
        // to the new employer (so we can re-use it instead of duplicating it).
        // -------------------------------------------------------------------
        Map<Id, List<npe5__Affiliation__c>> affiliationsByContactId =
            new Map<Id, List<npe5__Affiliation__c>>();

        for (npe5__Affiliation__c affiliation : [
                SELECT Id,
                       npe5__Contact__c,
                       npe5__Organization__c,
                       npe5__Status__c,
                       npe5__Primary__c,
                       npe5__StartDate__c,
                       npe5__EndDate__c
                FROM npe5__Affiliation__c
                WHERE npe5__Contact__c IN :contactIds
                  AND (npe5__Status__c = :STATUS_CURRENT OR npe5__Primary__c = true)]) {

            List<npe5__Affiliation__c> perContact = affiliationsByContactId.get(affiliation.npe5__Contact__c);
            if (perContact == null) {
                perContact = new List<npe5__Affiliation__c>();
                affiliationsByContactId.put(affiliation.npe5__Contact__c, perContact);
            }
            perContact.add(affiliation);
        }

        Date today = Date.today();
        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : contactIds) {

            Contact contact = contactsById.get(contactId);
            if (contact == null) {
                continue; // unknown or inaccessible Contact - skip it
            }

            Id employerId = employerByContactId.get(contactId);
            List<npe5__Affiliation__c> affiliations = affiliationsByContactId.get(contactId);

            npe5__Affiliation__c currentPrimary;      // the Affiliation flagged Primary today
            npe5__Affiliation__c employerAffiliation; // an existing Current Affiliation to the new employer

            if (affiliations != null) {
                for (npe5__Affiliation__c affiliation : affiliations) {
                    if (affiliation.npe5__Primary__c == true) {
                        currentPrimary = affiliation;
                    }
                    if (affiliation.npe5__Organization__c == employerId
                            && affiliation.npe5__Status__c == STATUS_CURRENT
                            && (employerAffiliation == null || affiliation.npe5__Primary__c == true)) {
                        employerAffiliation = affiliation;
                    }
                }
            }

            // The Organization already is this Contact's primary affiliation:
            // leave everything exactly as it is, do not create a duplicate.
            if (contact.npsp__Primary_Affiliation__c == employerId
                    || (employerAffiliation != null && employerAffiliation.npe5__Primary__c == true)) {
                continue;
            }

            // Retire the previous primary employer. NPSP uses this change to
            // clear / re-point Contact.npsp__Primary_Affiliation__c.
            if (currentPrimary != null && currentPrimary != employerAffiliation) {
                currentPrimary.npe5__Status__c  = STATUS_FORMER;
                currentPrimary.npe5__Primary__c = false;
                currentPrimary.npe5__EndDate__c = today;
                affiliationsToUpdate.add(currentPrimary);
            }

            if (employerAffiliation != null) {
                // Re-use the Affiliation that already exists for this employer.
                employerAffiliation.npe5__Status__c  = STATUS_CURRENT;
                employerAffiliation.npe5__Primary__c = true;
                employerAffiliation.npe5__EndDate__c = null;
                affiliationsToUpdate.add(employerAffiliation);
            } else {
                affiliationsToInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c      = contactId,
                    npe5__Organization__c = employerId,
                    npe5__Status__c       = STATUS_CURRENT,
                    npe5__Primary__c      = true,
                    npe5__StartDate__c    = today
                ));
            }
        }

        // DML 1 of 2 - demote old primaries / promote an existing Affiliation.
        if (!affiliationsToUpdate.isEmpty()) {
            update affiliationsToUpdate;
        }

        // DML 2 of 2 - create the new primary Affiliations. NPSP's Affiliation
        // trigger keeps Contact.npsp__Primary_Affiliation__c in sync for us.
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }
}
