public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one NPSP Data Import record per gift
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c = gift.firstName;
            di.npsp__Contact1_Lastname__c = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c = gift.giftDate;
            di.npsp__Donation_Donor__c = 'Contact1';
            dataImports.add(di);
        }

        insert dataImports;

        // Process synchronously using NPSP's Data Import Apex API
        npsp.DataImportService.processDataImports(dataImports);

        // Re-query the processed Data Import records to get NPSP's results
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :dataImports
        ]);

        // Build results in input order
        for (npsp__DataImport__c di : dataImports) {
            ImportResult res = new ImportResult();
            npsp__DataImport__c processed = processedById.get(di.Id);
            if (processed != null) {
                res.success = (processed.npsp__Status__c == 'Imported');
                res.contactId = processed.npsp__Contact1Imported__c;
                res.opportunityId = processed.npsp__DonationImported__c;
                res.errorMessage = res.success ? null : processed.npsp__FailureInformation__c;
            } else {
                res.success = false;
                res.errorMessage = 'Data Import record not found after processing.';
            }
            results.add(res);
        }

        return results;
    }
}
