/**
 * GauAllocationService
 *
 * Creates percentage-based GAU Allocations on an Opportunity, replacing whatever
 * GAU Allocations already exist on that Opportunity.
 *
 * Design notes
 * ------------
 * - Only npsp__Percent__c is populated on the new Allocation records.
 *   npsp__Amount__c is deliberately left null so that NPSP's own allocation
 *   engine derives Amount = Opportunity.Amount * Percent / 100 and keeps the
 *   derived amounts in sync whenever the Opportunity Amount is later changed.
 *   Writing Amount ourselves would break that behaviour.
 * - All validation happens before any DML so a bad request never leaves the
 *   Opportunity with a partially replaced set of allocations.
 * - The parent Opportunity is locked (FOR UPDATE) so two concurrent gift-entry
 *   sessions cannot interleave their delete-then-insert replace operations.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    private static final Decimal MAX_TOTAL_PERCENT = 100;

    /**
     * Replaces the GAU Allocations of the given Opportunity with one Allocation
     * per entry of percentByGauId.
     *
     * @param opportunityId  Opportunity whose allocations are being replaced.
     * @param percentByGauId GAU Id -> percentage (60 means 60%). Total must not
     *                       exceed 100; anything below 100 stays unallocated.
     * @return the inserted Allocation records.
     * @throws AllocationException when the input is invalid or a GAU is inactive.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // ------------------------------------------------------------------
        // 1. Validate the request. No DML has occurred yet.
        // ------------------------------------------------------------------
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required to create GAU Allocations.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU Allocation percentage is required.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A General Accounting Unit Id cannot be null.');
            }
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException(
                    'The Allocation percentage for General Accounting Unit ' + gauId +
                    ' must be greater than 0.');
            }
            totalPercent += percent;
        }
        if (totalPercent > MAX_TOTAL_PERCENT) {
            throw new AllocationException(
                'GAU Allocation percentages cannot total more than 100%. Current total: ' +
                totalPercent + '%.');
        }

        // Lock the Opportunity so concurrent replace operations are serialized.
        List<Opportunity> opportunities = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            FOR UPDATE
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }

        // Every GAU must exist and must be active.
        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :percentByGauId.keySet()
        ]);
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit not found: ' + gauId);
            }
            // Compare against true so a null checkbox is treated as inactive.
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('General Accounting Unit is inactive: ' + gauId);
            }
        }

        // ------------------------------------------------------------------
        // 2. Replace the existing allocations.
        // ------------------------------------------------------------------
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
                // npsp__Amount__c intentionally not set: NPSP calculates it from
                // the Opportunity Amount and the percentage, and recalculates it
                // whenever the Opportunity Amount changes.
            ));
        }
        insert newAllocations;

        // Re-read so the caller gets NPSP-computed values (Amount, Payment link,
        // etc.) while preserving the order of the incoming map.
        Map<Id, npsp__Allocation__c> insertedById = new Map<Id, npsp__Allocation__c>([
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__General_Accounting_Unit__c,
                   npsp__Amount__c,
                   npsp__Percent__c,
                   npsp__Payment__c,
                   npsp__Campaign__c,
                   npsp__Recurring_Donation__c
            FROM npsp__Allocation__c
            WHERE Id IN :newAllocations
        ]);

        List<npsp__Allocation__c> result = new List<npsp__Allocation__c>();
        for (npsp__Allocation__c allocation : newAllocations) {
            result.add(insertedById.get(allocation.Id));
        }
        return result;
    }
}
