public with sharing class SoftCreditService {
    public class SoftCreditException extends Exception {}
    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Collect IDs for bulk queries
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Opportunity and Contact are required');
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }
        if (oppIds.isEmpty()) {
            return;
        }

        // Query Opportunities
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        // Query existing OpportunityContactRoles
        List<OpportunityContactRole> existingOCRs = [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ];
        Map<String, List<OpportunityContactRole>> ocrMap = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingOCRs) {
            String key = ocr.OpportunityId + '|' + ocr.ContactId;
            if (!ocrMap.containsKey(key)) {
                ocrMap.put(key, new List<OpportunityContactRole>());
            }
            ocrMap.get(key).add(ocr);
        }

        // Query existing Partial Soft Credits
        List<npsp__Partial_Soft_Credit__c> existingPSCs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ];
        Map<String, List<npsp__Partial_Soft_Credit__c>> pscMap = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : existingPSCs) {
            String key = psc.npsp__Opportunity__c + '|' + psc.npsp__Contact__c;
            if (!pscMap.containsKey(key)) {
                pscMap.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscMap.get(key).add(psc);
        }

        // Validate all requests before any DML
        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive: ' + req.amount);
            }
            if (opp.Amount == null) {
                throw new SoftCreditException('Opportunity amount is null for opportunity: ' + req.opportunityId);
            }
            if (req.amount > opp.Amount) {
                throw new SoftCreditException('Amount exceeds opportunity amount: ' + req.amount + ' > ' + opp.Amount);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Cannot soft credit the primary contact: ' + req.contactId);
            }
        }

        // Prepare records for DML
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> ocrToUse = new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();

        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        Map<String, npsp__Partial_Soft_Credit__c> pscToUse = new Map<String, npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToDelete = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            String key = req.opportunityId + '|' + req.contactId;

            // Handle OpportunityContactRole
            List<OpportunityContactRole> ocrs = ocrMap.get(key);
            OpportunityContactRole chosenOCR;
            if (ocrs == null || ocrs.isEmpty()) {
                chosenOCR = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
            } else {
                chosenOCR = ocrs[0];
                chosenOCR.Role = req.role;
                // If there are duplicates, delete the extras
                for (Integer i = 1; i < ocrs.size(); i++) {
                    ocrsToDelete.add(ocrs[i]);
                }
            }
            ocrsToUpsert.add(chosenOCR);
            ocrToUse.put(key, chosenOCR);

            // Handle Partial Soft Credit
            List<npsp__Partial_Soft_Credit__c> pscs = pscMap.get(key);
            npsp__Partial_Soft_Credit__c chosenPSC;
            if (pscs == null || pscs.isEmpty()) {
                chosenPSC = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role
                );
            } else {
                chosenPSC = pscs[0];
                chosenPSC.npsp__Amount__c = req.amount;
                chosenPSC.npsp__Role_Name__c = req.role;
                // If there are duplicates, delete the extras
                for (Integer i = 1; i < pscs.size(); i++) {
                    pscsToDelete.add(pscs[i]);
                }
            }
            pscsToUpsert.add(chosenPSC);
            pscToUse.put(key, chosenPSC);
        }

        // DML 1: Upsert OpportunityContactRoles to get Ids for new ones
        upsert ocrsToUpsert;

        // Link PSCs to their OCR Ids
        for (String key : pscToUse.keySet()) {
            npsp__Partial_Soft_Credit__c psc = pscToUse.get(key);
            OpportunityContactRole ocr = ocrToUse.get(key);
            psc.npsp__Contact_Role_ID__c = ocr.Id;
        }

        // DML 2: Upsert Partial Soft Credits
        upsert pscsToUpsert;

        // DML 3: Delete extra PSCs if any
        if (!pscsToDelete.isEmpty()) {
            delete pscsToDelete;
        }

        // DML 4: Delete extra OCRs if any
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }
    }
}
