public with sharing class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('Number of payments must be at least 1.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('First payment date is required.');
        }
        if (opportunityId == null) {
            throw new PaymentPlanException('Opportunity ID is required.');
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            FOR UPDATE
        ];
        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }
        Opportunity opp = opportunities[0];
        if (opp.IsClosed) {
            throw new PaymentPlanException('Cannot schedule installments on a closed opportunity.');
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            FOR UPDATE
        ];

        Decimal outstanding = opp.Amount == null ? 0.0 : opp.Amount;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c p : existingPayments) {
            Boolean isPaid = p.npe01__Paid__c == true;
            Boolean isWrittenOff = p.npe01__Written_Off__c == true;
            if (isPaid || isWrittenOff) {
                Decimal paidAmount = p.npe01__Payment_Amount__c == null ? 0.0 : p.npe01__Payment_Amount__c;
                outstanding -= paidAmount;
            } else {
                paymentsToDelete.add(p);
            }
        }

        if (outstanding <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero.');
        }

        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }

        Decimal divisor = numberOfPayments;
        Decimal regularAmount = outstanding.divide(divisor, 2, RoundingMode.DOWN);
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount;
            if (i == numberOfPayments - 1) {
                amount = outstanding - (regularAmount * (numberOfPayments - 1));
            } else {
                amount = regularAmount;
            }

            npe01__OppPayment__c pmt = new npe01__OppPayment__c();
            pmt.npe01__Opportunity__c = opportunityId;
            pmt.npe01__Payment_Amount__c = amount;
            pmt.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            pmt.npe01__Paid__c = false;
            pmt.npe01__Written_Off__c = false;
            newPayments.add(pmt);
        }

        insert newPayments;
        return newPayments;
    }
}
