/**
 * GiftService
 * Records a received gift (Closed Won donation) in NPSP with Household Account model
 * and NPSP Payments enabled.
 */
public with sharing class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // Validate inputs
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('Contact ID is required.');
        }

        // Query the primary contact
        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact primaryContact = contacts[0];
        if (primaryContact.AccountId == null) {
            throw new IllegalArgumentException('Contact has no household account: ' + contactId);
        }

        // Query all household members
        List<Contact> householdMembers = [
            SELECT Id, FirstName, LastName
            FROM Contact
            WHERE AccountId = :primaryContact.AccountId
        ];

        // Build opportunity name
        String firstName = primaryContact.FirstName == null ? '' : primaryContact.FirstName;
        String lastName = primaryContact.LastName == null ? '' : primaryContact.LastName;
        String oppName = (firstName + ' ' + lastName).trim() + ' Donation ' + String.valueOf(giftDate);

        // Find Donation record type if it exists
        Id donationRecordTypeId = null;
        List<RecordType> donationRTs = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Opportunity' AND DeveloperName = 'Donation'
            LIMIT 1
        ];
        if (!donationRTs.isEmpty()) {
            donationRecordTypeId = donationRTs[0].Id;
        }

        // Create the Opportunity
        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = primaryContact.AccountId,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            npsp__Primary_Contact__c = primaryContact.Id,
            RecordTypeId = donationRecordTypeId
        );
        insert opp;

        // Ensure exactly one payment
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opp.Id
        ];
        if (!existingPayments.isEmpty()) {
            delete existingPayments;
        }
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        insert payment;

        // Reconcile contact roles
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opp.Id
        ];
        Map<Id, List<OpportunityContactRole>> rolesByContact = new Map<Id, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingRoles) {
            if (!rolesByContact.containsKey(ocr.ContactId)) {
                rolesByContact.put(ocr.ContactId, new List<OpportunityContactRole>());
            }
            rolesByContact.get(ocr.ContactId).add(ocr);
        }

        Set<Id> expectedContactIds = new Set<Id>();
        expectedContactIds.add(primaryContact.Id);
        for (Contact member : householdMembers) {
            if (member.Id != primaryContact.Id) {
                expectedContactIds.add(member.Id);
            }
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();

        // Delete roles for contacts not in the household
        for (Id contactIdKey : rolesByContact.keySet()) {
            if (!expectedContactIds.contains(contactIdKey)) {
                toDelete.addAll(rolesByContact.get(contactIdKey));
            }
        }

        // Primary contact: exactly one role, Donor, IsPrimary = true
        if (rolesByContact.containsKey(primaryContact.Id)) {
            List<OpportunityContactRole> roles = rolesByContact.get(primaryContact.Id);
            OpportunityContactRole keep = roles[0];
            keep.Role = 'Donor';
            keep.IsPrimary = true;
            toUpdate.add(keep);
            for (Integer i = 1; i < roles.size(); i++) {
                toDelete.add(roles[i]);
            }
        } else {
            toInsert.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId = primaryContact.Id,
                Role = 'Donor',
                IsPrimary = true
            ));
        }

        // Other household members: exactly one role, Household Member, IsPrimary = false
        for (Contact member : householdMembers) {
            if (member.Id == primaryContact.Id) continue;
            if (rolesByContact.containsKey(member.Id)) {
                List<OpportunityContactRole> roles = rolesByContact.get(member.Id);
                OpportunityContactRole keep = roles[0];
                keep.Role = 'Household Member';
                keep.IsPrimary = false;
                toUpdate.add(keep);
                for (Integer i = 1; i < roles.size(); i++) {
                    toDelete.add(roles[i]);
                }
            } else {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = opp.Id,
                    ContactId = member.Id,
                    Role = 'Household Member',
                    IsPrimary = false
                ));
            }
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }

        return opp.Id;
    }
}
