public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate && oldlist != null) {
            for (SObject sObj : oldlist) {
                if (sObj != null) {
                    oldOppsById.put(sObj.Id, (Opportunity)sObj);
                }
            }
        }

        List<SObject> tasksToInsert = new List<SObject>();

        for (SObject sObj : newlist) {
            if (sObj == null) {
                continue;
            }

            Opportunity opp = (Opportunity)sObj;

            if (!qualifies(opp)) {
                continue;
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpp = oldOppsById.get(opp.Id);
                if (oldOpp != null && qualifies(oldOpp)) {
                    continue;
                }
            }

            Task t = new Task();
            t.Subject = 'Major gift thank-you call';
            t.Priority = 'High';
            t.Status = 'Not Started';
            t.WhatId = opp.Id;
            t.WhoId = opp.npsp__Primary_Contact__c;
            t.OwnerId = opp.OwnerId;
            if (opp.CloseDate != null) {
                t.ActivityDate = opp.CloseDate.addDays(3);
            }

            tasksToInsert.add(t);
        }

        if (!tasksToInsert.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        }

        return dmlWrapper;
    }

    private static Boolean qualifies(Opportunity opp) {
        return opp != null
            && opp.StageName == 'Closed Won'
            && opp.Amount != null
            && opp.Amount >= 5000;
    }
}
