public with sharing class RecordAccessService {
    /**
     * Returns the subset of recordIds that the running user can edit.
     * Uses UserRecordAccess.HasEditAccess, which accounts for object permissions,
     * ownership, sharing, role hierarchy, View All/Modify All, etc.
     *
     * @param recordIds Set of record IDs to check. May contain nulls; nulls are ignored.
     * @return Set of record IDs the running user can edit. Never null.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Filter out nulls to avoid query issues
        Set<Id> validIds = new Set<Id>();
        for (Id recId : recordIds) {
            if (recId != null) {
                validIds.add(recId);
            }
        }
        if (validIds.isEmpty()) {
            return editable;
        }

        // Query UserRecordAccess for the running user. This object returns only records
        // the user has access to. If a record is not returned, the user has no access.
        // HasEditAccess already considers object permissions, sharing, role hierarchy,
        // View All/Modify All, etc.
        List<UserRecordAccess> accesses = [
            SELECT RecordId, HasEditAccess
            FROM UserRecordAccess
            WHERE UserId = :UserInfo.getUserId()
            AND RecordId IN :validIds
        ];

        for (UserRecordAccess access : accesses) {
            if (access.HasEditAccess) {
                editable.add(access.RecordId);
            }
        }

        return editable;
    }
}
