/**
 * Trigger Action: creates an onboarding Task for the Account owner whenever an Account
 * is created with Type 'Customer - Direct' or 'Customer - Channel'.
 *
 * Registered via Trigger_Action__mdt record TA_Account_CreateOnboardingTask (After Insert = Account, Order 10).
 * Bulk-safe: one insert statement per trigger execution; no DML at all when nothing qualifies.
 */
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    @TestVisible
    private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    @TestVisible
    private static final Integer ONBOARDING_DUE_IN_DAYS = 7;

    @TestVisible
    private static final String ONBOARDING_SUBJECT = 'Onboard new customer';

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        List<Account> newAccounts = (List<Account>) triggerNew;
        Date dueDate = Date.today().addDays(ONBOARDING_DUE_IN_DAYS);

        List<Task> onboardingTasks = new List<Task>();
        for (Account acct : newAccounts) {
            if (acct.Type == null || !ONBOARDING_ACCOUNT_TYPES.contains(acct.Type)) {
                continue;
            }

            onboardingTasks.add(
                new Task(
                    Subject = ONBOARDING_SUBJECT,
                    WhatId = acct.Id,
                    OwnerId = acct.OwnerId,
                    ActivityDate = dueDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                )
            );
        }

        // No qualifying Accounts => no DML at all.
        if (onboardingTasks.isEmpty()) {
            return;
        }

        // Single DML statement for the whole trigger execution (200-record data loads included).
        insert onboardingTasks;
    }
}
