/**
 * Imports (inserts) Contacts that already exist as customers in a legacy system.
 *
 * The insert is executed with the TAF action `TA_Contact_CreateWelcomeTask` bypassed, so
 * migrated customers do not receive a welcome Task, while all other Contact automation
 * (including the before-insert action `TA_Contact_FormatPhone`) still runs normally.
 *
 * TAF stores its bypass state in a static, transaction-wide variable, so the bypass is
 * always cleared before this method returns: any Contact inserted later in the same
 * transaction gets its welcome Task as usual.
 */
public with sharing class ContactImportService {
    /**
     * Name of the TAF action to skip. TAF identifies an action by the name of the Apex
     * class that implements the TriggerAction interface (here an after-insert action).
     */
    private static final String CREATE_WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    /**
     * Inserts the supplied Contacts in a single DML statement, bypassing the
     * `TA_Contact_CreateWelcomeTask` TAF action for that statement only.
     *
     * @param contacts the Contacts to insert. A null or empty list is a no-op.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        MetadataTriggerHandler.bypass(CREATE_WELCOME_TASK_ACTION);
        try {
            insert contacts;
        } finally {
            // Must be cleared explicitly: the bypass lives in a static variable for the
            // whole transaction and would otherwise also suppress the welcome Task for
            // every Contact inserted after this call.
            MetadataTriggerHandler.clearBypass(CREATE_WELCOME_TASK_ACTION);
        }
    }
}
