/**
 * Service class for reassigning ownership of Accounts and their Contacts.
 * Account trigger actions are bypassed during the ownership change.
 */
public with sharing class AccountOwnershipService {
    /**
     * Reassigns the owner of the specified Accounts and all their Contacts.
     * Account trigger actions (TAF) are bypassed for the duration of this method.
     * Contact trigger actions run normally.
     *
     * @param accountIds  Set of Account IDs to reassign (up to 200).
     * @param newOwnerId  The User ID of the new owner.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Preserve any existing Account bypass so we don't clear a caller's bypass.
        Boolean accountAlreadyBypassed = TriggerBase.isBypassed(Account.SObjectType);

        try {
            // Bypass all Account trigger actions for this transaction.
            TriggerBase.bypass(Account.SObjectType);

            // Update Accounts. Account TAF actions are bypassed.
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accountId : accountIds) {
                accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }
            update accountsToUpdate;

            // Query and update all Contacts of those Accounts.
            // Contact trigger actions run normally.
            List<Contact> contactsToUpdate = [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :accountIds
            ];
            for (Contact contactRecord : contactsToUpdate) {
                contactRecord.OwnerId = newOwnerId;
            }
            if (!contactsToUpdate.isEmpty()) {
                update contactsToUpdate;
            }
        } finally {
            // Restore normal Account automation unless it was already bypassed by the caller.
            if (!accountAlreadyBypassed) {
                TriggerBase.clearBypass(Account.SObjectType);
            }
        }
    }
}
