 * in-memory records instead of inserting/updating data: this class performs no DML and no SOQL.
 * The fake Ids come from TAF's TriggerTestUtility so the action can pair every "new" record with
 * its "old" counterpart through the Id-keyed map it builds internally.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    @IsTest
    static void rejectsReductionOfMoreThanHalf() {
        Id opportunityId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(Id = opportunityId, Amount = 1000)
        };
        List<Opportunity> triggerNew = new List<Opportunity>{
            new Opportunity(Id = opportunityId, Amount = 499)
        };

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);
        Test.stopTest();

