        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);
        Test.stopTest();

        assertNoError(triggerNew[0], 'Reduction from 1000 to 500');
        Assert.isTrue(triggerNew[0].Amount == 500, 'The action must not change the Amount.');
    }

    @IsTest
    static void acceptsIncrease() {
