```apex
/**
 * Trigger Action (Trigger Actions Framework) that prevents two Contacts of the same Account
 * from sharing the same email address, compared case-insensitively.
 *
 * Contacts without an Account or without an Email are never checked.
 * Registered for before insert and before update through Trigger_Action__mdt
 * (TA_Contact_PreventDuplicateEmail_BI / _BU, Order 10).
 *
 * Bulk safe: at most one SOQL query per trigger execution; offending records receive a
 * record level error so that partial saves keep working.
 */
public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    /**
     * Before insert: every checkable contact of the incoming list is a candidate.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> candidates = new List<Contact>();
        for (SObject record : triggerNew) {
            Contact candidate = (Contact) record;
            if (isCheckable(candidate)) {
                candidates.add(candidate);
            }
        }
        validateNoDuplicateEmail(candidates);
    }

    /**
     * Before update: only contacts whose Email or AccountId actually changed are checked.
     * Legacy duplicates therefore never block unrelated edits.
     */
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldContactsById = new Map<Id, Contact>();
        for (SObject record : triggerOld) {
            oldContactsById.put(record.Id, (Contact) record);
        }

        List<Contact> candidates = new List<Contact>();
        for (SObject record : triggerNew) {
            Contact candidate = (Contact) record;
            Contact oldContact = oldContactsById.get(candidate.Id);
            if (oldContact == null) {
                continue;
            }
            Boolean emailChanged = candidate.Email != oldContact.Email;
            Boolean accountChanged = candidate.AccountId != oldContact.AccountId;
            if ((emailChanged || accountChanged) && isCheckable(candidate)) {
                candidates.add(candidate);
            }
        }
        validateNoDuplicateEmail(candidates);
    }

    /**
     * @return true when the contact takes part in the duplicate check at all.
     */
    private static Boolean isCheckable(Contact candidate) {
        return candidate.AccountId != null && String.isNotBlank(candidate.Email);
    }

    /**
     * Applies the rule for the given candidates, preserving their list order.
     * At most one SOQL query is issued for the whole trigger execution.
     */
    private static void validateNoDuplicateEmail(List<Contact> candidates) {
        if (candidates.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        Set<Id> selfIds = new Set<Id>();
        for (Contact candidate : candidates) {
            accountIds.add(candidate.AccountId);
            if (candidate.Id != null) {
                selfIds.add(candidate.Id);
            }
        }

        // Single query per trigger execution: everything that could already be a duplicate.
        Set<String> existingKeys = new Set<String>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
        ]) {
            if (selfIds.contains(existing.Id)) {
                continue; // a contact never conflicts with itself
            }
            existingKeys.add(buildKey(existing.AccountId, existing.Email));
        }

        // First candidate in the save wins its key, every later one is rejected.
        Set<String> claimedKeys = new Set<String>();
        for (Contact candidate : candidates) {
            String key = buildKey(candidate.AccountId, candidate.Email);
            Boolean conflictsWithExistingContact = existingKeys.contains(key);
            Boolean conflictsWithEarlierContactInThisSave = !claimedKeys.add(key);
            if (conflictsWithExistingContact || conflictsWithEarlierContactInThisSave) {
                candidate.addError(ERROR_MESSAGE);
            }
        }
    }

    /**
     * Case-insensitive key that identifies an (Account, Email) pair.
     */
    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + ':' + email.toLowerCase();
    }
}
