/**
 * Trigger Action: TA_Lead_NormalizeContactInfo
 *
 * Registered on the Lead object (Trigger_Action__mdt record, Order 10) to run in the
 * before insert context via MetadataTriggerHandler.
 *
 * Purpose: clean up messy Lead data created by Web-to-Lead and list imports so the values
 * are already correct on the very first save of the record.
 *   - Email:      trimmed and lower-cased (null stays null)
 *   - Company:    trimmed
 *   - LeadSource: defaults to 'Web' when blank, otherwise left untouched
 *
 * Bulk safe: a single pass over Trigger.new with no SOQL and no DML.
 */
public with sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Lead> newLeads = (List<Lead>) triggerNew;

        for (Lead lead : newLeads) {
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = DEFAULT_LEAD_SOURCE;
            }
        }
    }
}
