/**
 * Logs an audit Task on every Opportunity whose Amount changes on update.
 *
 * Order__c 10, so it runs before TA_Opportunity_RoundAmount (Order__c 20). The rounding
 * action re-updates the same Opportunities in the same transaction, which re-enters the
 * after update context; TriggerBase.idToNumberOfTimesSeenAfterUpdate lets this action run
 * only on the first pass, so a rounding-only Amount change is never logged and at most one
 * "Amount changed" Task is created per Opportunity per transaction.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static final String SUBJECT = 'Amount changed';
    private static final String STATUS_COMPLETED = 'Completed';

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opp : triggerNew) {
            // Skip every pass after the first one in this transaction (e.g. the re-entrant
            // update performed by TA_Opportunity_RoundAmount).
            Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(opp.Id);
            if (timesSeen != null && timesSeen > 1) {
                continue;
            }

            Opportunity oldOpp = oldById.get(opp.Id);
            if (oldOpp == null || opp.Amount == oldOpp.Amount) {
                continue;
            }

            tasksToInsert.add(
                new Task(Subject = SUBJECT, WhatId = opp.Id, Status = STATUS_COMPLETED)
            );
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
