/**
 * Singleton query holder for the Contact trigger actions.
 *
 * The inner class Service is the trigger action (Order 1) that populates the
 * map; the other before insert actions read it, so an entire trigger execution
 * costs exactly one Account query no matter how many actions need the parents.
 *
 * inherited sharing: the class runs in the sharing context of the trigger entry
 * point (MetadataTriggerHandler), so the query neither escalates nor restricts
 * access beyond what the caller already has.
 */
public inherited sharing class TA_Contact_Queries {
    @TestVisible
    private static TA_Contact_Queries instance;

    /** Parent Accounts of the Contacts in the current trigger execution, keyed by Account Id. */
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Queries the parent Accounts referenced by the supplied Contacts and replaces
     * the cached map. Always called first in the before insert context, and on every
     * trigger execution, so later DML in the same transaction cannot leave stale data.
     */
    private void loadAccounts(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact contactRecord : contacts) {
            if (contactRecord.AccountId != null) {
                accountIds.add(contactRecord.AccountId);
            }
        }

        Map<Id, Account> freshAccountsById = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            freshAccountsById = new Map<Id, Account>([
                SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                FROM Account
                WHERE Id IN :accountIds
            ]);
        }

        this.accountsById = freshAccountsById;
    }

    /**
     * Trigger action that loads the singleton's Account map. Registered in
     * Trigger_Action__mdt as TA_Contact_Queries.Service with Order__c = 1.
     */
    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            List<Contact> contacts = new List<Contact>();
            for (SObject record : triggerNew) {
                contacts.add((Contact) record);
            }
            TA_Contact_Queries.getInstance().loadAccounts(contacts);
        }
    }
}
