/**
 * Before insert: when a new Contact has an Account and its mailing address is
 * completely blank, inherit the Account's billing address.
 *
 * Never queries Accounts itself - it reads the map prepared by
 * TA_Contact_Queries.Service, which runs first in the before insert context.
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact contactRecord = (Contact) record;

            if (contactRecord.AccountId == null) {
                continue;
            }
            if (!hasBlankMailingAddress(contactRecord)) {
                continue;
            }

            Account parentAccount = accountsById.get(contactRecord.AccountId);
            if (parentAccount == null) {
                continue;
            }

            contactRecord.MailingStreet = parentAccount.BillingStreet;
            contactRecord.MailingCity = parentAccount.BillingCity;
            contactRecord.MailingPostalCode = parentAccount.BillingPostalCode;
            contactRecord.MailingCountry = parentAccount.BillingCountry;
        }
    }

    private static Boolean hasBlankMailingAddress(Contact contactRecord) {
        return String.isBlank(contactRecord.MailingStreet)
            && String.isBlank(contactRecord.MailingCity)
            && String.isBlank(contactRecord.MailingPostalCode)
            && String.isBlank(contactRecord.MailingCountry);
    }
}
